basic-example:
import { useState } from 'react';
import { DsDateTimePicker } from '@primasoftllc/design-system';

export function Example() {
  const [value, setValue] = useState('2026-10-19T09:00');
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsDateTimePicker label="Начало поездки" value={value} onChange={setValue} hint="Часовой пояс приложения: Europe/Minsk. Значение не переводится в UTC."/>
    <output aria-live="polite">Выбрано: {value || 'не указано'}</output>
  </div>;
}

form-validation:
import { useState } from 'react';
import { DsDateTimePicker, DsButton } from '@primasoftllc/design-system';

export function Example() {
  const [result, setResult] = useState('');
  return <form style={{display:'flex',flexDirection:'column',gap:16}} onSubmit={event => {
    event.preventDefault();
    setResult('Сохранено: ' + new FormData(event.currentTarget).get('scheduled'));
  }} onReset={() => setResult('')}>
    <DsDateTimePicker label="Начало поездки" name="scheduled" defaultValue="2026-10-19T09:00"
      required min="2026-10-01T00:00" max="2026-10-31T23:59"
      hint="Допустимый интервал: 2026-10-01T00:00 — 2026-10-31T23:59."/>
    <div style={{display:'flex',flexWrap:'wrap',gap:8}}>
      <DsButton type="submit">Сохранить</DsButton>
      <DsButton type="reset" tone="secondary">Сбросить</DsButton>
    </div>
    <span role="status">{result}</span>
  </form>;
}

