import { DsDateTimePicker } from '@primasoftllc/design-system';

export function Example() {
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsDateTimePicker label="Подтверждённое значение" defaultValue="2026-10-19T09:00" readOnly hint="Изменение доступно после отмены подтверждения."/>
    <DsDateTimePicker label="Недоступное значение" defaultValue="2026-10-19T09:00" disabled hint="Недостаточно прав для изменения."/>
    <DsDateTimePicker label="Проверка сервером" defaultValue="2026-10-19T09:00" error="Это время уже занято. Выберите другое."/>
  </div>;
}
